async function refreshCoach(){
 const d=engine?.getDashboard?.()||{weaknesses:[],active_days_7:0,active_seconds_30:0,event_count_30:0,accuracy_30:null,maintenance:{reviews:[]}};
 document.getElementById('v51Days7')&&(document.getElementById('v51Days7').textContent=d.active_days_7||0);document.getElementById('v51Min30')&&(document.getElementById('v51Min30').textContent=Math.round((d.active_seconds_30||0)/60));document.getElementById('v51Attempts30')&&(document.getElementById('v51Attempts30').textContent=d.event_count_30||0);document.getElementById('v51Accuracy')&&(document.getElementById('v51Accuracy').textContent=d.accuracy_30==null?'—':d.accuracy_30+'%');
 const weak=d.weaknesses||[],box=document.getElementById('v51FocusList'),title=document.getElementById('v51FocusTitle');if(box){if(!weak.length){title.textContent=isEN?'Profile building':'Profil en construction';box.innerHTML='<div class="v51-empty">'+L.focusEmpty+'</div>'}else{title.textContent=labelSkill(weak[0].key);box.innerHTML=weak.slice(0,4).map(w=>`<div class="v51-focus-item"><b>${esc(labelSkill(w.key))}</b><span>${w.mastery}%</span></div>`).join('')}}
 const reviews=d.maintenance?.reviews||[],last=reviews[reviews.length-1];document.getElementById('v51Retention')&&(document.getElementById('v51Retention').textContent=last?last.score+'%':L.retentionNone);document.getElementById('v51RetentionNote')&&(document.getElementById('v51RetentionNote').textContent=last?(isEN?'Measured on the latest Cold Case.':'Mesurée sur le dernier Cold Case.'):'');
 try{const cloud=await engine?.fetchCloudDashboard?.();if(cloud){const cd=cloud.dashboard||cloud;if(document.getElementById('v51Days7')&&cd.active_days_7!=null)document.getElementById('v51Days7').textContent=cd.active_days_7;if(document.getElementById('v51Min30')&&cd.active_seconds_30!=null)document.getElementById('v51Min30').textContent=Math.round(cd.active_seconds_30/60)}}catch(e){}
}

function targeted(container,skill,selected,correct){
 if(!container)return;container.querySelector('.v51-targeted')?.remove();const d=document.createElement('div');d.className='v51-targeted';d.innerHTML=`<b>🎯 ${L.target} · ${esc(labelSkill(skill))}</b>${esc(isEN?`You selected “${selected}” instead of “${correct}”.`:`Vous avez choisi « ${selected} » au lieu de « ${correct} ».`)} ${L.remember}`;const fb=container.querySelector('.micro-feedback,.n2-feedback,.duel-feedback');if(fb)fb.insertAdjacentElement('afterend',d);else container.appendChild(d)
}
function clearTargeted(container){container?.querySelector('.v51-targeted')?.remove()}
function instrumentLearning(){
 document.querySelectorAll('.choice').forEach(btn=>btn.addEventListener('click',()=>setTimeout(()=>{const card=btn.closest('.case-card');if(!card)return;const isCorrect=btn.classList.contains('correct'),q=btn.dataset.q,kind=btn.dataset.kind,term=card.dataset.term||'',skill=termDomain(term),correctIndex=Number(kind==='main'?card.dataset.answer:card.dataset.nuance),options=[...card.querySelectorAll(`.choice[data-kind="${kind}"]`)];const correctText=options.find(x=>Number(x.dataset.i)===correctIndex)?.textContent.trim().replace(/^[A-D1-4]\s*/,'')||'';const selected=btn.textContent.trim().replace(/^[A-D1-4]\s*/,'');engine?.record({activityKey:`n1.case.${q}.${kind}`,competencyKey:skill,eventType:kind==='main'?'n1_identification':'n1_discrimination',correct:isCorrect,answerCode:btn.dataset.i,metadata:{term,selected,correct:correctText}});if(isCorrect)clearTargeted(card);else targeted(card,skill,selected,correctText);refreshCoach()},0)));
 document.querySelectorAll('.duel-btn').forEach(btn=>btn.addEventListener('click',()=>setTimeout(()=>{const card=btn.closest('.duel');if(!card)return;const ok=btn.classList.contains('correct'),term=card.dataset.answer||'',skill=termDomain(term);engine?.record({activityKey:`n1.duel.${btn.dataset.duel}`,competencyKey:skill,eventType:'n1_duel',correct:ok,answerCode:btn.dataset.value,metadata:{selected:btn.dataset.value,correct:term}});if(ok)clearTargeted(card);else targeted(card,skill,btn.dataset.value,term);refreshCoach()},0)));
 document.querySelectorAll('[data-n2-single]').forEach(btn=>btn.addEventListener('click',()=>setTimeout(()=>{const sid=btn.dataset.n2Single,card=document.getElementById('n2-'+sid);if(!card)return;const corr=document.getElementById('n2corr-'+sid),ans=Number(corr?.dataset.answer),opts=[...card.querySelectorAll('[data-n2-single]')],correctText=opts.find(x=>Number(x.dataset.i)===ans)?.textContent.trim().replace(/^[A-D]\s*/,'')||'',selected=btn.textContent.trim().replace(/^[A-D]\s*/,''),ok=btn.classList.contains('correct'),skill='n2.'+(card.dataset.comp||'other');engine?.record({activityKey:`n2.station.${sid}`,competencyKey:skill,eventType:'n2_decision',correct:ok,answerCode:btn.dataset.i,metadata:{selected,correct:correctText}});if(ok)clearTargeted(card);else targeted(card,skill,selected,correctText);refreshCoach()},0)));
 document.querySelectorAll('button[onclick^="gradeN2Multi"]').forEach(btn=>btn.addEventListener('click',()=>setTimeout(()=>{const m=(btn.getAttribute('onclick')||'').match(/gradeN2Multi\('([^']+)'\)/);if(!m)return;const sid=m[1],card=document.getElementById('n2-'+sid),status=((typeof n2state!=='undefined'&&n2state.stations)?n2state.stations:{})[sid],ok=status==='acquis',skill='n2.'+(card?.dataset.comp||'other');engine?.record({activityKey:`n2.station.${sid}`,competencyKey:skill,eventType:'n2_multi_decision',correct:ok,metadata:{station:sid}});if(ok)clearTargeted(card);else targeted(card,skill,isEN?'Current selection':'Sélection actuelle',isEN?'Rebuild the branch set from the discriminating data.':'Reconstituez l’ensemble des branches à partir des données discriminantes.');refreshCoach()},0)));
 window.addEventListener('psylab:learning-event',()=>refreshCoach());
}

